package com.inventra.backend.controller;
import com.inventra.backend.dto.*; import com.inventra.backend.model.StockReservation; import com.inventra.backend.repository.ReservationRepository; import com.inventra.backend.service.InventoryCoreService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/reservations") public class ReservationController {private final ReservationRepository r;private final InventoryCoreService inv;public ReservationController(ReservationRepository r,InventoryCoreService i){this.r=r;inv=i;}@GetMapping("/orders/{orderId}") public List<StockReservation> byOrder(@PathVariable String orderId){return r.findByOrderId(orderId);}@PostMapping public StockReservation create(@RequestParam String warehouseId,@Valid @RequestBody ReservationRequest x){inv.reserve(warehouseId,x.productId(),x.quantity(),x.orderId());StockReservation s=new StockReservation();s.setOrderId(x.orderId());s.setWarehouseId(warehouseId);s.setProductId(x.productId());s.setQuantity(x.quantity());return r.save(s);}}
